package de.lazytv.pro;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.graphics.drawable.*;import android.location.*;import android.os.Bundle;import android.util.Base64;import android.view.*;import android.widget.*;import java.util.*;import java.net.*;import java.io.*;import org.json.*;import de.lazytv.pro.live.LiveTvActivity;import de.lazytv.pro.playlist.*;

public class MainActivity extends Activity{
 private TextView location,weather,clock,prayer;private LinearLayout rail;private String prayerText="Kohët e namazit nuk janë ngarkuar ende.";private Bitmap premiumTileSheet;
 @Override protected void onCreate(Bundle b){super.onCreate(b);buildHome();}
 private void buildHome(){boolean portrait=getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_PORTRAIT;LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(portrait?14:24),dp(portrait?10:14),dp(portrait?14:24),dp(10));root.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.rgb(2,8,26),Color.rgb(8,44,78),Color.rgb(2,14,34)}));
  LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView brand=text("LazyTV PRO",portrait?22:26,Color.WHITE,true);top.addView(brand,new LinearLayout.LayoutParams(dp(portrait?96:170),dp(54)));location=text("GPS",portrait?13:15,Color.rgb(150,220,255),true);location.setCompoundDrawablesWithIntrinsicBounds(android.R.drawable.ic_menu_mylocation,0,0,0);location.setCompoundDrawablePadding(dp(7));weather=text("--°C",portrait?13:15,Color.WHITE,true);weather.setCompoundDrawablesWithIntrinsicBounds(android.R.drawable.ic_menu_compass,0,0,0);weather.setCompoundDrawablePadding(dp(7));clock=text(now(),portrait?18:20,Color.WHITE,true);top.addView(location,new LinearLayout.LayoutParams(0,dp(54),1));top.addView(weather,new LinearLayout.LayoutParams(dp(portrait?88:125),dp(54)));top.addView(clock,new LinearLayout.LayoutParams(dp(portrait?68:90),dp(54)));root.addView(top);
  LinearLayout utility=new LinearLayout(this);utility.setGravity(Gravity.CENTER_VERTICAL);TextView date=text(new java.text.SimpleDateFormat("EEE, dd.MM.yyyy",Locale.getDefault()).format(new Date()),portrait?12:13,Color.rgb(120,190,235),false);utility.addView(date,new LinearLayout.LayoutParams(0,dp(40),1));prayer=text("  Namazi",portrait?12:13,Color.rgb(255,201,92),true);prayer.setGravity(Gravity.CENTER);prayer.setCompoundDrawablesWithIntrinsicBounds(android.R.drawable.ic_menu_today,0,0,0);prayer.setCompoundDrawablePadding(dp(7));card(prayer,Color.rgb(7,38,64));utility.addView(prayer,new LinearLayout.LayoutParams(dp(portrait?110:138),dp(36)));root.addView(utility);
  String[] names={"LIVE TV","PREMIUM","MOVIES","SERIES","PLAYLISTS","CATCH-UP","FAVORITES","SETTINGS","RELOAD","SERVERS","EXIT"};Button[] bs=new Button[names.length];
  if(portrait){ScrollView sv=new ScrollView(this);LinearLayout rows=new LinearLayout(this);rows.setOrientation(LinearLayout.VERTICAL);rows.setGravity(Gravity.CENTER_HORIZONTAL);for(int i=0;i<names.length;i+=2){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER);for(int j=0;j<2&&i+j<names.length;j++){int n=i+j;bs[n]=tile(names[n]);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(112),1);lp.setMargins(dp(6),dp(6),dp(6),dp(6));row.addView(bs[n],lp);}rows.addView(row,new LinearLayout.LayoutParams(-1,-2));}sv.addView(rows);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));}
  else{HorizontalScrollView hs=new HorizontalScrollView(this);hs.setFillViewport(true);hs.setHorizontalScrollBarEnabled(false);rail=new LinearLayout(this);rail.setOrientation(LinearLayout.HORIZONTAL);rail.setGravity(Gravity.CENTER);for(int i=0;i<names.length;i++){bs[i]=tile(names[i]);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(172),dp(132));lp.setMargins(dp(9),dp(10),dp(9),dp(10));rail.addView(bs[i],lp);}hs.addView(rail);root.addView(hs,new LinearLayout.LayoutParams(-1,0,1));}
  Playlist a=active();TextView footer=text("ACTIVE PROVIDER  •  "+(a==null?"FREE TV":a.getName()),11,Color.rgb(145,200,230),false);root.addView(footer,new LinearLayout.LayoutParams(-1,dp(28)));setContentView(root);
  bs[0].setOnClickListener(v->openLive());bs[1].setOnClickListener(v->openServerTen());bs[2].setOnClickListener(v->openCatalog("MOVIES"));bs[3].setOnClickListener(v->openCatalog("SERIES"));bs[4].setOnClickListener(v->openPlaylists());bs[5].setOnClickListener(v->Toast.makeText(this,"Catch-up aktivizohet kur provider-i ofron arkivë",Toast.LENGTH_LONG).show());bs[6].setOnClickListener(v->openCatalog(null));bs[7].setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));bs[8].setOnClickListener(v->reload());bs[9].setOnClickListener(v->showServers());bs[10].setOnClickListener(v->finish());prayer.setOnClickListener(v->showPrayer());bs[0].requestFocus();updateLocal();}
 private TextView text(String s,int z,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setGravity(Gravity.CENTER_VERTICAL);if(bold)t.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);return t;}
 private Button tile(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setTextSize(14);b.setAllCaps(false);b.setGravity(Gravity.CENTER);b.setFocusable(true);b.setFocusableInTouchMode(true);Drawable d=categoryIcon(s);int iconSize=isPremiumArtwork(s)?dp(54):dp(34);d.setBounds(0,0,iconSize,iconSize);b.setCompoundDrawables(null,d,null,null);b.setCompoundDrawablePadding(dp(8));style(b,false,s);b.setOnFocusChangeListener((v,f)->{v.animate().scaleX(f?1.08f:1f).scaleY(f?1.08f:1f).setDuration(110).start();style((Button)v,f,s);if(f&&v.getParent() instanceof LinearLayout){final View x=v;v.post(()->x.getParent().requestChildFocus(x,x));}});return b;}
 private boolean isPremiumArtwork(String s){return s.equals("LIVE TV")||s.equals("MOVIES")||s.equals("SERIES")||s.equals("FAVORITES");}
 private Drawable premiumArtwork(String s){try{if(premiumTileSheet==null){InputStream in=getAssets().open("home_tiles.jpg.b64");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[]buf=new byte[4096];int n;while((n=in.read(buf))>0)out.write(buf,0,n);in.close();byte[]raw=Base64.decode(out.toString("UTF-8").trim(),Base64.DEFAULT);premiumTileSheet=BitmapFactory.decodeByteArray(raw,0,raw.length);}if(premiumTileSheet==null)return null;int index=s.equals("LIVE TV")?0:s.equals("MOVIES")?1:s.equals("SERIES")?2:s.equals("FAVORITES")?3:-1;if(index<0)return null;int cw=premiumTileSheet.getWidth()/4,ch=premiumTileSheet.getHeight()/2;Bitmap crop=Bitmap.createBitmap(premiumTileSheet,index*cw,0,cw,ch);return new BitmapDrawable(getResources(),crop);}catch(Exception ignored){return null;}}
 private Drawable categoryIcon(String s){Drawable premium=premiumArtwork(s);if(premium!=null)return premium;final int TV=1,CROWN=2,MOVIE=3,SERIES=4,LIST=5,CLOCK=6,HEART=7,GEAR=8,RELOAD=9,SERVER=10,EXIT=11;int kind=s.equals("LIVE TV")?TV:s.equals("PREMIUM")?CROWN:s.equals("MOVIES")?MOVIE:s.equals("SERIES")?SERIES:s.equals("PLAYLISTS")?LIST:s.equals("CATCH-UP")?CLOCK:s.equals("FAVORITES")?HEART:s.equals("SETTINGS")?GEAR:s.equals("RELOAD")?RELOAD:s.equals("SERVERS")?SERVER:EXIT;return new Drawable(){Paint p=new Paint(3);@Override public void draw(Canvas c){float w=getBounds().width(),h=getBounds().height(),cx=w/2,cy=h/2;p.setColor(Color.WHITE);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(2,w*.075f));p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);Path q=new Path();if(kind==TV){c.drawRoundRect(w*.12f,h*.18f,w*.88f,h*.78f,w*.08f,w*.08f,p);q.moveTo(w*.43f,h*.36f);q.lineTo(w*.68f,h*.49f);q.lineTo(w*.43f,h*.63f);q.close();p.setStyle(Paint.Style.FILL);c.drawPath(q,p);c.drawLine(w*.38f,h*.88f,w*.62f,h*.88f,p);}else if(kind==CROWN){q.moveTo(w*.12f,h*.35f);q.lineTo(w*.3f,h*.55f);q.lineTo(w*.5f,h*.25f);q.lineTo(w*.7f,h*.55f);q.lineTo(w*.88f,h*.35f);q.lineTo(w*.8f,h*.75f);q.lineTo(w*.2f,h*.75f);q.close();c.drawPath(q,p);c.drawLine(w*.23f,h*.86f,w*.77f,h*.86f,p);}else if(kind==MOVIE){c.drawRoundRect(w*.14f,h*.25f,w*.86f,h*.78f,w*.06f,w*.06f,p);c.drawLine(w*.16f,h*.25f,w*.28f,h*.12f,p);c.drawLine(w*.38f,h*.25f,w*.5f,h*.12f,p);c.drawLine(w*.6f,h*.25f,w*.72f,h*.12f,p);c.drawLine(w*.14f,h*.25f,w*.86f,h*.25f,p);q.moveTo(w*.43f,h*.4f);q.lineTo(w*.68f,h*.52f);q.lineTo(w*.43f,h*.65f);q.close();p.setStyle(Paint.Style.FILL);c.drawPath(q,p);}else if(kind==SERIES){c.drawRoundRect(w*.12f,h*.18f,w*.66f,h*.72f,w*.05f,w*.05f,p);c.drawRoundRect(w*.34f,h*.36f,w*.88f,h*.88f,w*.05f,w*.05f,p);q.moveTo(w*.52f,h*.5f);q.lineTo(w*.73f,h*.62f);q.lineTo(w*.52f,h*.74f);q.close();p.setStyle(Paint.Style.FILL);c.drawPath(q,p);}else if(kind==LIST){for(int i=0;i<3;i++){float y=h*(.28f+i*.22f);c.drawCircle(w*.2f,y,w*.035f,p);c.drawLine(w*.34f,y,w*.82f,y,p);}}else if(kind==CLOCK){c.drawCircle(cx,cy,w*.34f,p);c.drawLine(cx,cy,cx,h*.3f,p);c.drawLine(cx,cy,w*.68f,h*.61f,p);}else if(kind==HEART){q.moveTo(cx,h*.82f);q.cubicTo(w*.08f,h*.55f,w*.14f,h*.23f,w*.36f,h*.28f);q.cubicTo(w*.45f,h*.3f,w*.49f,h*.38f,cx,h*.42f);q.cubicTo(w*.51f,h*.38f,w*.55f,h*.3f,w*.64f,h*.28f);q.cubicTo(w*.86f,h*.23f,w*.92f,h*.55f,cx,h*.82f);c.drawPath(q,p);}else if(kind==GEAR){c.drawCircle(cx,cy,w*.16f,p);c.drawCircle(cx,cy,w*.31f,p);for(int i=0;i<8;i++){double a=i*Math.PI/4;c.drawLine(cx+(float)Math.cos(a)*w*.31f,cy+(float)Math.sin(a)*w*.31f,cx+(float)Math.cos(a)*w*.42f,cy+(float)Math.sin(a)*w*.42f,p);}}else if(kind==RELOAD){c.drawArc(w*.18f,h*.18f,w*.82f,h*.82f,-45,285,false,p);q.moveTo(w*.76f,h*.12f);q.lineTo(w*.9f,h*.27f);q.lineTo(w*.68f,h*.29f);p.setStyle(Paint.Style.FILL);c.drawPath(q,p);}else if(kind==SERVER){for(int i=0;i<3;i++){float y=h*(.18f+i*.25f);c.drawRoundRect(w*.16f,y,w*.84f,y+h*.16f,w*.04f,w*.04f,p);c.drawCircle(w*.27f,y+h*.08f,w*.025f,p);}}else{c.drawRoundRect(w*.18f,h*.18f,w*.58f,h*.82f,w*.04f,w*.04f,p);c.drawLine(w*.42f,cy,w*.86f,cy,p);c.drawLine(w*.72f,h*.36f,w*.86f,cy,p);c.drawLine(w*.72f,h*.64f,w*.86f,cy,p);}}@Override public void setAlpha(int a){p.setAlpha(a);}@Override public void setColorFilter(android.graphics.ColorFilter f){p.setColorFilter(f);}@Override public int getOpacity(){return android.graphics.PixelFormat.TRANSLUCENT;}};}
 private void style(Button b,boolean f,String s){int accent=s.equals("PREMIUM")||s.equals("SERVERS")?Color.rgb(245,164,45):s.equals("MOVIES")||s.equals("FAVORITES")?Color.rgb(214,54,87):s.equals("SERIES")?Color.rgb(133,65,190):Color.rgb(0,124,194);GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,f?new int[]{accent,Color.rgb(4,42,73)}:new int[]{Color.rgb(8,42,69),Color.rgb(3,18,35)});g.setCornerRadius(dp(20));g.setStroke(dp(f?3:1),f?Color.WHITE:Color.rgb(34,79,112));b.setBackground(g);b.setElevation(dp(f?12:3));}
 private void card(View v,int c){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(14));g.setStroke(dp(1),Color.rgb(38,112,150));v.setBackground(g);}
 private void openLive(){Playlist p=active();Intent i=new Intent(this,LiveTvActivity.class);if(p!=null){i.putExtra("playlist_id",p.getId());i.putExtra("source_scope","PROVIDER");}else{i.putExtra("builtin_live",true);i.putExtra("source_scope","TRIAL");}startActivity(i);}
 private void openServerTen(){Intent i=new Intent(this,LiveTvActivity.class);i.putExtra("source_scope","SERVER_10");i.putExtra("server_id","SERVER_10");startActivity(i);}
 private void showServers(){PlaylistStorage s=new PlaylistStorage(this);List<Playlist>a=s.getAll();String[] names=new String[a.size()+1];names[0]="Premium • Server 10 • MANAGED";for(int n=0;n<a.size();n++)names[n+1]=a.get(n).getName()+" • "+a.get(n).getType().name();new AlertDialog.Builder(this).setTitle("Servers / Providers").setItems(names,(d,w)->{if(w==0){openServerTen();return;}Playlist p=a.get(w-1);s.setActive(p.getId());recreate();}).setPositiveButton("Manage",(d,w)->openPlaylists()).show();}
 private Playlist active(){PlaylistStorage s=new PlaylistStorage(this);String id=s.getActiveId();return id==null?null:s.get(id);}private void openPlaylists(){startActivity(new Intent(this,PlaylistManagerActivity.class));}
 private void openCatalog(String type){Playlist p=active();if(p==null){openPlaylists();return;}Intent i=new Intent(this,de.lazytv.pro.catalog.CatalogActivity.class);i.putExtra("playlist_id",p.getId());i.putExtra("source_scope","PROVIDER");if(type!=null)i.putExtra(de.lazytv.pro.catalog.CatalogActivity.EXTRA_TYPE,type);startActivity(i);}
 private void reload(){Playlist p=active();if(p==null){openPlaylists();return;}Intent i=new Intent(this,LiveTvActivity.class);i.putExtra("playlist_id",p.getId());i.putExtra("source_scope","PROVIDER");i.putExtra("force_reload",true);startActivity(i);}
 private void updateLocal(){String saved=getSharedPreferences("lazytv_local",MODE_PRIVATE).getString("city","");if(!saved.isEmpty())location.setText(saved);String temp=getSharedPreferences("lazytv_local",MODE_PRIVATE).getString("temp","");if(!temp.isEmpty())weather.setText(temp);String pt=getSharedPreferences("lazytv_local",MODE_PRIVATE).getString("prayers","");if(!pt.isEmpty())prayerText=pt;if(android.os.Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_COARSE_LOCATION},41);return;}try{LocationManager lm=(LocationManager)getSystemService(LOCATION_SERVICE);Location l=lm==null?null:lm.getLastKnownLocation(LocationManager.NETWORK_PROVIDER);if(l==null&&lm!=null)l=lm.getLastKnownLocation(LocationManager.GPS_PROVIDER);if(l!=null){Location x=l;new Thread(()->loadLocal(x)).start();}}catch(Exception ignored){}}
 private void loadLocal(Location l){String city="GPS";try{List<android.location.Address>a=new Geocoder(this,Locale.getDefault()).getFromLocation(l.getLatitude(),l.getLongitude(),1);if(a!=null&&!a.isEmpty()){android.location.Address x=a.get(0);String country=x.getCountryName()==null?"":x.getCountryName();String town=x.getLocality()==null?"GPS":x.getLocality();city=(country.isEmpty()?"":country+" • ")+town;}}catch(Exception ignored){}String c=city;runOnUiThread(()->{location.setText(c);getSharedPreferences("lazytv_local",MODE_PRIVATE).edit().putString("city",c).apply();});loadWeather(l);loadPrayers(l);}
 private String get(String url)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();try{c.setConnectTimeout(6000);c.setReadTimeout(6000);c.setRequestProperty("Accept","application/json");BufferedReader r=new BufferedReader(new InputStreamReader(c.getInputStream()));StringBuilder b=new StringBuilder();String x;while((x=r.readLine())!=null)b.append(x);r.close();return b.toString();}finally{c.disconnect();}}
 private void loadWeather(Location l){try{String u="https://api.open-meteo.com/v1/forecast?latitude="+l.getLatitude()+"&longitude="+l.getLongitude()+"&current=temperature_2m&temperature_unit=celsius";double t=new JSONObject(get(u)).getJSONObject("current").getDouble("temperature_2m");String value=Math.round(t)+"°C";getSharedPreferences("lazytv_local",MODE_PRIVATE).edit().putString("temp",value).apply();runOnUiThread(()->weather.setText(value));}catch(Exception ignored){}}
 private void loadPrayers(Location l){try{String u="https://api.aladhan.com/v1/timings?latitude="+l.getLatitude()+"&longitude="+l.getLongitude()+"&method=3";JSONObject t=new JSONObject(get(u)).getJSONObject("data").getJSONObject("timings");String value="Sabahu  "+clean(t.optString("Fajr"))+"\nLindja  "+clean(t.optString("Sunrise"))+"\nDreka  "+clean(t.optString("Dhuhr"))+"\nIkindia  "+clean(t.optString("Asr"))+"\nAkshami  "+clean(t.optString("Maghrib"))+"\nJacia  "+clean(t.optString("Isha"));prayerText=value;getSharedPreferences("lazytv_local",MODE_PRIVATE).edit().putString("prayers",value).apply();}catch(Exception ignored){}}
 private String clean(String s){int p=s.indexOf(' ');return p>0?s.substring(0,p):s;}
 private void showPrayer(){new AlertDialog.Builder(this).setTitle("Kohët e Namazit").setMessage(prayerText).setPositiveButton("OK",null).show();}
 private String now(){return new java.text.SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date());}@Override public void onRequestPermissionsResult(int r,String[]p,int[]g){super.onRequestPermissionsResult(r,p,g);if(r==41)updateLocal();}private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
}
